def fill(grid, key):
    n=len(grid); m=len(grid[0])
    for P in range(1, m+1):
        res={}
        ok=True
        for r in range(n):
            for c in range(m):
                if grid[r][c]!=0:
                    k=key(r,c)%P
                    if k in res and res[k]!=grid[r][c]:
                        ok=False; break
                    res[k]=grid[r][c]
            if not ok: break
        if ok and len(res)>1:
            # also require every observed residue maps consistently -> already ensured
            return [[res[key(r,c)%P] for c in range(m)] for r in range(n)]
    return None

def transform(grid):
    n=len(grid); m=len(grid[0])
    # diagonal stripes first
    out = fill(grid, lambda r,c: c-r) 
    if out is None:
        out = fill(grid, lambda r,c: r)
    return out

